// bundler can no longer drop either half.
export const getOrderTotal = ({ amount, customerId }: { amount: number; customerId: string }): number =>
	amount * (getCustomerTier({ customerId }) === 'gold' ? 0.9 : 1);

interface RunRecorder {
	record: (params: { step: string }) => void;
}

const createRunRecorder = (): RunRecorder => {
	const steps: string[] = [];

	return { record: ({ step }) => steps.push(step) };
};

// The shared part is held as a value and delegated to — visible at the seam.
export class RefactorRun implements RunRecorder {
	private readonly recorder = createRunRecorder();

	record({ step }: { step: string }): void {
		this.recorder.record({ step });
	}

	decline({ step }: { step: string }): void {
		this.recorder.record({ step: `declined:${step}` });
	}
}

// The one licensed base: subclassing is the platform's only way to make a
// typed, instanceof-checkable error.
export class RunLockError extends Error {}

// Error-family chains stay licensed too.
export class StaleRunLockError extends RunLockError {}

class RunState {
	protected steps: string[] = [];

	record({ step }: { step: string }): void {
		this.steps.push(step);
	}
}

export class RefactorRun extends RunState {
	decline({ step }: { step: string }): void {
		this.record({ step: `declined:${step}` });
	}
}

