rules.prose:
## Type Assertion

Never write an `as` cast in source code. A cast tells the compiler to trust you instead of proving the type. Narrow instead, with `typeof`, `instanceof` or a discriminated union. When a value cannot be narrowed where it is used, such as a value of type `unknown` from a library, write a type guard or a validation function for it.

This includes text arriving at a boundary, such as a JSON payload, a query parameter or a database value: a string is not yet a member of a named constant's union, so convert it with a small validation function, such as `parseAction`, never `as Action`.

A type guard must test the value. One that returns `true` without checking is a cast under another name.

`as const` is not a cast: it fixes a literal's type, and it stays.

```typescript
// Incorrect: the compiler takes your word for it
return (value as string).toUpperCase();

// Correct: the check proves it
if (typeof value === 'string') {
	return value.toUpperCase();
}
```

fixtures.text:
// `as const` is not the assertion this rule bans — it freezes literals, and the
// named-constants document asks for it by name.
export const PayloadKind = {
	Label: 'label',
	Amount: 'amount',
} as const;

export type PayloadKind = (typeof PayloadKind)[keyof typeof PayloadKind];

// Narrowed rather than asserted, so the branch that returns a string is the
// branch the compiler proved.
export const readLabel = ({ payload }: { payload: Record<string, unknown> }): string => {
	const label = payload.label;

	return typeof label === 'string' ? label.toUpperCase() : '';
};

// The payload's field is `unknown`, and the cast says it is a string rather
// than proving it — a value from outside now travels as a checked one.
export const readLabel = ({ payload }: { payload: Record<string, unknown> }): string => (payload.label as string).toUpperCase();

import { expect, describe, test, jest } from '@jest/globals';
import { placeOrder } from './placeOrder';

const setupOrder = () => {
	const repository = { save: () => undefined };
	const saveSpy = jest.spyOn(repository, 'save');

	return { repository, saveSpy };
};

describe('placeOrder', () => {
	test('saves the order it was given', () => {
		const { repository, saveSpy } = setupOrder();

		placeOrder({ repository, order: { id: 'a' } });

		expect(saveSpy).toHaveBeenCalledWith({ id: 'a' });
	});
});

import { expect, describe, test, jest } from '@jest/globals';
import { placeOrder } from './placeOrder';

// The repository is an object the test already holds — replacing its whole
// module hides every other method the unit may touch.
const mockSave = jest.fn<(order: { id: string }) => void>();

jest.mock('./orderRepository', () => ({
	orderRepository: { save: (order: { id: string }) => mockSave(order) },
}));

describe('placeOrder', () => {
	test('saves the order it was given', () => {
		placeOrder({ order: { id: 'a' } });

		expect(mockSave).toHaveBeenCalledWith({ id: 'a' });
	});
});
